import type {StoreRecord} from '@xh/hoist/data';
import {shallowEqualArrays} from '@xh/hoist/utils/impl';
import {isEmpty} from 'lodash';
import type {BaseRow} from '../row/BaseRow';
import {ExposedLeafRow, type LeafRow} from '../row/LeafRow';
import type {ParentRow} from '../row/ParentRow';
import type {View} from '../View';

/**
 * Cache of the BaseRows generated by a View, allowing rows - along with their published data
 * objects and `cubeRowDigest` stamps - to be reused across regenerations of the View's results.
 *
 * Reuse invariant: a cached row is returned only when its published data can be made identical
 * to that of a from-scratch rebuild. A leaf must be backed by the same (immutable) cube
 * StoreRecord and match the view's current exposed/hidden leaf class - its data then needs no
 * work at all. An aggregate row is reused whenever requested (its id fixes its dimension path,
 * so only its children and aggregate values can vary): when its children array is identical and
 * provably current it also needs no work, otherwise its aggregates are recomputed in place, with
 * its digest bumped only if some value actually changed. "Provably current" = used by the
 * previous generation, or no cube data change since last use - a dormant row's children may have
 * been updated in place under other parents, so identical children do not imply identical
 * values. Bucket rows reuse only on an identical children array - changed membership would
 * require re-deriving their BucketSpec. Reused rows keep their `cubeRowDigest`, letting
 * connected stores - which read that stamp via a View-installed reuse digest - skip record
 * rebuilds for them.
 *
 * Views with aggregators that do not declare {@link Aggregator.dependsOnChildrenOnly}, or with
 * fields that define a `canAggregateFn` - both of which may read the per-generation
 * AggregationContext - additionally re-evaluate those fields on every reused parent row each
 * generation, again bumping digests only for values that actually changed. Bucket stamps,
 * `lockFn` and `omitFn` are re-derived for all rows on every generation and need no constraint.
 *
 * Retention: entries not requested by a generation are retained for potential later reuse - e.g.
 * leaves for records currently excluded by filter, ready should the filter widen again. Two
 * bounds apply. Parents orphaned by a grouping change are evicted at the end of the generation
 * that orphaned them - each distinct grouping would otherwise accumulate a cached parent set for
 * the life of the view, as their live-record children would keep them from ever sweeping. And
 * the cache sweeps at the end of a generation when it has outgrown the rows in current use by
 * 50%+, dropping exactly the rows whose underlying cube records have been removed or replaced.
 * Dead entries - and the replaced records they pin - are therefore bounded by a fraction of the
 * view's working set.
 *
 * @internal
 */
export class RowCache {
    private view: View;
    private rows = new Map<string, BaseRow>();
    private recomputeAggs = false;
    private exposedLeaves = false;
    private sweptAsOf: number = null;
    private generation = 0;
    private evictUnusedParents = false;

    // Monotonic cube-data version, advanced when a generation observes changed source data.
    // Keyed on RecordSet identity - replaced on every real data change, preserved by no-change
    // reloads - rather than the ms-resolution `cube.lastUpdated`, which can falsely equate a
    // tick landing in the same millisecond as a prior generation.
    private dataVersion = 0;
    private lastSeenRecords: unknown = null;

    // Stats for the current generation - logged by endGeneration()
    private reused = 0;
    private rebuilt = 0;
    private created = 0;
    private recomputed = 0;
    private evicted = 0;
    private removed = 0;
    private sweepTime = 0;

    constructor(view: View) {
        this.view = view;
    }

    get size(): number {
        return this.rows.size;
    }

    get(id: string): BaseRow {
        return this.rows.get(id);
    }

    /**
     * Return the cached row for id if it satisfies the reuse invariant, otherwise build via
     * `fn` and cache the result. Leaves validate against `record`, bucket rows against
     * `children`; aggregate rows always reuse, recomputing in place as needed.
     */
    getOrCreate<T extends BaseRow>(
        id: string,
        children: BaseRow[],
        fn: () => T,
        record?: StoreRecord
    ): T {
        let ret = this.rows.get(id);
        if (ret) {
            if (ret.isLeaf) {
                if (
                    (ret as LeafRow).cubeRecord === record &&
                    ret instanceof ExposedLeafRow === this.exposedLeaves
                ) {
                    this.reused++;
                    return ret as T;
                }
            } else {
                const childrenEqual = shallowEqualArrays(ret.children, children);
                // BucketRows with changed children rebuild - their BucketSpec and label would
                // need re-deriving from the new membership.
                if (childrenEqual || ret.isAggregate) {
                    this.reuseParentRow(ret as ParentRow, children, childrenEqual);
                    this.reused++;
                    return ret as T;
                }
            }
            this.rebuilt++;
        } else {
            this.created++;
        }
        ret = fn();
        ret.valuesChangedGen = this.generation;
        if (!ret.isLeaf) this.stampParentRow(ret as ParentRow);
        this.rows.set(id, ret);
        return ret as T;
    }

    // Reuse a cached parent, adopting the passed children (re-pointing each at this row - a
    // child may have been adopted by another parent while this one sat out a generation) and
    // recomputing aggregates as needed, with the digest bumped only on actual value change.
    private reuseParentRow(row: ParentRow, children: BaseRow[], childrenEqual: boolean) {
        // Skip the full recompute only when provably current: children identical, none of them
        // (re)built or changed in place this generation (rows recompute bottom-up, so child
        // value changes must cascade to reused ancestors), AND either used by the previous
        // generation (in the live tree, so tick propagation maintained it) or no cube data
        // change since last use (nothing could drift while dormant). A dormant row's children
        // may have been updated in place under other parents, so identical children alone do
        // not imply identical values.
        const {generation} = this,
            current =
                childrenEqual &&
                !children.some(it => it.valuesChangedGen === generation) &&
                (row.lastUsedGen === generation - 1 ||
                    row.lastUsedDataVersion === this.dataVersion);

        if (!current || this.recomputeAggs) this.recomputed++;
        if (row.reuse(children, !current, this.recomputeAggs)) {
            row.valuesChangedGen = generation;
            this.view.noteRowDataMutated(row.data);
        }
        this.stampParentRow(row);
    }

    private stampParentRow(row: ParentRow) {
        row.lastUsedGen = this.generation;
        row.lastUsedDataVersion = this.dataVersion;
    }

    beginGeneration() {
        const {view} = this;
        this.generation++;
        const records = view.cube.store._filtered;
        if (records !== this.lastSeenRecords) {
            this.dataVersion++;
            this.lastSeenRecords = records;
        }
        this.recomputeAggs =
            !view.aggregatorsAreSimple || !isEmpty(view._canAggregateFnFieldsByDepth[0]);
        this.exposedLeaves = view.exposesLeaves;
        this.reused = this.rebuilt = this.created = this.recomputed = 0;
        this.evicted = this.removed = this.sweepTime = 0;
    }

    endGeneration() {
        if (this.evictUnusedParents) {
            this.evictUnusedParents = false;
            this.doEvictUnusedParents();
        }
        this.sweep();
        this.view.logDebug(
            `Generated rows: reused=${this.reused} recomputed=${this.recomputed} ` +
                `rebuilt=${this.rebuilt} created=${this.created} ` +
                `cached=${this.size} evicted=${this.evicted} removed=${this.removed} ` +
                `sweepTime=${this.sweepTime.toFixed(1)}ms`
        );
    }

    /**
     * Request eviction of any parent rows not used by the coming generation, at its end. Called
     * ahead of a query change that alters the grouping - see View.pruneCacheForQueryChange.
     */
    evictUnusedParentsAtGenerationEnd() {
        this.evictUnusedParents = true;
    }

    clear() {
        this.rows.clear();
        this.evictUnusedParents = false;
    }

    /**
     * Remove all parent (aggregate/bucket) rows, and null the parent pointers of the retained
     * leaves - every pointer is dead once all parents are dropped, and would otherwise pin the
     * dead chains in memory.
     */
    removeParentRows() {
        const {rows} = this;
        rows.forEach((row, id) => {
            if (row.isLeaf) {
                row.parent = null;
            } else {
                rows.delete(id);
            }
        });
    }

    // Drop parents orphaned by a grouping change - each distinct grouping would otherwise
    // accumulate a cached parent set for the life of the view, as live-record children keep such
    // parents from ever sweeping. Then null dangling parent pointers on retained rows, so
    // evicted chains are not pinned in memory. Filter-dormant parents are retained across
    // filter-only changes (which never trigger this pass) and are bounded at one full-data
    // tree's worth; any evicted here alongside the orphans (their subtree filtered out during a
    // regroup) simply rebuild if the filter widens again.
    private doEvictUnusedParents() {
        const {rows, generation} = this;
        rows.forEach((row, id) => {
            if (!row.isLeaf && (row as ParentRow).lastUsedGen !== generation) {
                rows.delete(id);
                this.evicted++;
            }
        });
        if (!this.evicted) return;
        rows.forEach(row => {
            const {parent} = row;
            if (parent && rows.get(parent.id) !== parent) row.parent = null;
        });
    }

    // Drop rows whose underlying cube records have been removed or replaced. Skipped unless the
    // cache has outgrown the generation's live rows by 50%+ and cube data has changed since the
    // last sweep - rows can only die with their records.
    private sweep() {
        const live = this.reused + this.rebuilt + this.created,
            asOf = this.view.cube.lastUpdated;
        if (asOf === this.sweptAsOf || this.size <= 1.5 * live) return;

        const start = performance.now(),
            {rows} = this,
            {store} = this.view.cube,
            memo = new Map<BaseRow, boolean>(),
            startSize = rows.size;

        const isRetained = (row: BaseRow): boolean => {
            let ret = memo.get(row);
            if (ret === undefined) {
                ret = row.isLeaf
                    ? store.getById((row as LeafRow).cubeRecordId) === (row as LeafRow).cubeRecord
                    : !!row.children?.every(it => rows.get(it.id) === it && isRetained(it));
                memo.set(row, ret);
            }
            return ret;
        };

        rows.forEach((row, id) => {
            if (!isRetained(row)) rows.delete(id);
        });

        this.sweptAsOf = asOf;
        this.removed = startSize - rows.size;
        this.sweepTime = performance.now() - start;
    }
}
